EDITORIAL_BAN = ["network breathes", "not a conversation", "wrong by construction", "tight cycle",
                 "workhorse", "dissolving", "boundaries are tested", "teaches padding", "paying off",
                 "buys nothing", "honest use", "informal lanes", "honesty rule", "dying quietly",
                 "which is the point", "the one idea", "here is the trap", "keeps it honest",
                 "earning its keep"]


def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.188.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.187.0"' not in init:
        sys.exit("ABORT: not at v3.187.0.")
    if "quotations" not in data:
        sys.exit("ABORT: quotations module not found in data file.")

    problems = _validate("SELL3", LESSONS_S3, QUESTIONS_S3, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_S3))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — SELL3 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_S3)
    print(f"SELL 3 v3: {len(LESSONS_S3)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_S3):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["quotations"]["lessons"] = LESSONS_S3
    data["quotations"]["questions"] = bank
    data["quotations"]["desc"] = ("Quotations in ZhiftERP: the field walk — party and list header checks, the row discipline, taxes per template, terms selected not typed, and the pre-issue verification; the rate discipline — pre-fill first, the deviation ladder with specific named concessions, margin visibility, and the monthly deviations read; validity and the revision procedure with the negotiation file; the offer pack — owned terms templates, print discipline, and the transmission record; the pipeline reads — open quotations, outcome marking with reason codes, the conversion read, and deviation-versus-outcome; and conversion to order with the four checks, partial acceptance, and the clean handoff.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.187.0"', '"3.188.0"'))
    print("  data: SELLING 3 lessons + bank REPLACED (style v3, formal manual register)")
    print("wrote __version__ -> 3.188.0")


if __name__ == "__main__":
    main()
